#!/usr/bin/env node
// Takes the CAD operation icons PartBuddy uses from Zoo Design Studio (KittyCAD/modeling-app,
// MIT licence) at one pinned commit and writes them as path data (ADR 0023):
//   apps/desktop/src/renderer/src/ui/zooIcons.ts        generated, do not edit
//   apps/desktop/src/renderer/src/ui/zooIcons.LICENSE   Zoo's MIT licence, shipped with the icons
// General UI icons stay Tabler. To take a newer version, change ZOO_COMMIT and run again.
//
// Usage: node tools/icons/build-zoo-icons.mjs

import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ZOO_REPOSITORY = 'KittyCAD/modeling-app';
const ZOO_COMMIT = 'd01b321d5540cbcc59d8d7941cfb6056bbe1c91b';

/** PartBuddy name → icon key in Zoo's src/components/CustomIcon.tsx. */
const ICONS = {
  extrude: 'extrude',
  revolve: 'revolve',
  sweep: 'sweep',
  loft: 'loft',
  fillet: 'fillet3d',
  chamfer: 'chamfer3d',
  // Zoo's `shell` (diagonal) blurs with `hole` at 14 px; `hollow` shows the wall.
  shell: 'hollow',
  hole: 'hole',
  patternLinear: 'patternLinear3d',
  patternCircular: 'patternCircular3d',
  mirror: 'mirror3d',
  split: 'split',
  helix: 'helix',
  union: 'booleanUnion',
  subtract: 'booleanSubtract',
  intersect: 'booleanIntersect',
  plane: 'plane',
  sketch: 'sketch',
  dimension: 'dimension',
};

const root = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const out = join(root, 'apps', 'desktop', 'src', 'renderer', 'src', 'ui');

async function fetchText(path) {
  const url = `https://raw.githubusercontent.com/${ZOO_REPOSITORY}/${ZOO_COMMIT}/${path}`;
  const response = await fetch(url);
  if (!response.ok) throw new Error(`${url}: HTTP ${response.status}`);
  return response.text();
}

const source = await fetchText('src/components/CustomIcon.tsx');
const licence = await fetchText('LICENSE');

const icons = {};
for (const [name, key] of Object.entries(ICONS)) {
  const entry = source.match(new RegExp(`\\n  '?${key}'?: \\(\\s*(<svg[\\s\\S]*?</svg>)\\s*\\),`));
  if (!entry) throw new Error(`icon "${key}" not found in CustomIcon.tsx`);
  const svg = entry[1];
  if (!/viewBox="0 0 20 20"/.test(svg)) throw new Error(`icon "${key}" is not on Zoo's 20 px grid`);
  const paths = [...svg.matchAll(/<path([\s\S]*?)\/>/g)].map(([, attributes]) => {
    const d = attributes.match(/\sd="([^"]+)"/)?.[1];
    if (!d) throw new Error(`icon "${key}" has a path without data`);
    if (/\sstroke=/.test(attributes)) throw new Error(`icon "${key}" uses strokes; only filled paths are taken over`);
    return { d, evenOdd: /fillRule="evenodd"/.test(attributes) };
  });
  if (paths.length === 0) throw new Error(`icon "${key}" has no paths`);
  icons[name] = paths;
}

const lines = [
  '// Generated by tools/icons/build-zoo-icons.mjs. Do not edit.',
  `// Source: https://github.com/${ZOO_REPOSITORY}/blob/${ZOO_COMMIT}/src/components/CustomIcon.tsx`,
  '// Licence: MIT, Copyright (c) 2023 The Zoo Authors (zooIcons.LICENSE).',
  '',
  '/** Filled path data on Zoo\'s 20 × 20 grid, one entry per PartBuddy CAD icon. */',
  'export const zooIcons = {',
  ...Object.entries(icons).map(
    ([name, paths]) =>
      `  ${name}: [${paths.map(({ d, evenOdd }) => `{ d: '${d}', evenOdd: ${evenOdd} }`).join(', ')}],`,
  ),
  '} as const satisfies Record<string, readonly { d: string; evenOdd: boolean }[]>;',
  '',
  'export type ZooIconName = keyof typeof zooIcons;',
  '',
];
writeFileSync(join(out, 'zooIcons.ts'), lines.join('\n'));
writeFileSync(join(out, 'zooIcons.LICENSE'), licence);
console.log(`${Object.keys(icons).length} icons from ${ZOO_REPOSITORY}@${ZOO_COMMIT.slice(0, 7)}`);
